def outside_95(fd: FunnelData) -> int:
    c95: FunnelContour = next(c for c in fd.contours if c.mass == 0.95)
    z = (c95.upper[-1] - fd.pooled) / c95.se[-1]
    return int(np.sum(np.abs(np.asarray(fd.y) - fd.pooled) > z * np.asarray(fd.se)))

